<script>document.addEventListener('DOMContentLoaded',()=>{const b=document.getElementById('satirlar'),money=n=>'₺'+Number(n||0).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2});let i=1;function calc(){let a=0,k=0;b.querySelectorAll('.doc-line').forEach(r=>{let m=+r.querySelector('.miktar').value||0,f=+r.querySelector('.fiyat').value||0,d=+r.querySelector('.iskonto').value||0,o=+r.querySelector('.kdv').value||0,n=m*f*(1-d/100),v=n*o/100;a+=n;k+=v;r.querySelector('.line-total').textContent=money(n+v)});document.getElementById('ara-toplam').textContent=money(a);document.getElementById('kdv-toplam').textContent=money(k);document.getElementById('genel-toplam').textContent=money(a+k)}function bind(r){r.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',calc));r.querySelector('.satir-sil').addEventListener('click',()=>{if(b.children.length>1){r.remove();calc()}})}bind(b.firstElementChild);document.getElementById('satir-ekle').addEventListener('click',()=>{let r=b.firstElementChild.cloneNode(true);r.querySelectorAll('input,select').forEach(x=>{x.name=x.name.replace(/\[\d+\]/,'['+i+']');if(x.classList.contains('miktar'))x.value=1;else if(x.classList.contains('iskonto'))x.value=0;else if(x.tagName==='SELECT')x.selectedIndex=0;else x.value=''});r.querySelector('.line-total').textContent='₺0,00';b.appendChild(r);bind(r);i++});document.getElementById('cari-select').addEventListener('change',e=>{const o=e.target.selectedOptions[0];if(o?.dataset.unvan)document.getElementById('musteri-unvan').value=o.dataset.unvan});calc()})</script>
